const draw = () => {
  ctx.clearRect(0, 0, width, height);
  // ship – triangle pointing up
  ctx.fillStyle = ship.shield > 0 ? 'gold' : 'white';
  ctx.beginPath();
  ctx.moveTo(ship.x, ship.y - ship.radius);
  ctx.lineTo(ship.x - ship.radius, ship.y + ship.radius);
  ctx.lineTo(ship.x + ship.radius, ship.y + ship.radius);
  ctx.closePath();
  ctx.fill();
  // asteroids – gray circles
  ctx.fillStyle = '#777';
  asteroids.forEach(a => {
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
    ctx.fill();
  });
  // energy orbs – cyan circles
  ctx.fillStyle = '#0ff';
  orbs.forEach(o => {
    ctx.beginPath();
    ctx.arc(o.x, o.y, o.radius, 0, Math.PI * 2);
    ctx.fill();
  });
  // HUD – fuel bar
  ctx.fillStyle = 'lime';
  const barWidth = 100;
  ctx.fillRect(10, 10, (ship.fuel / 100) * barWidth, 8);
  ctx.strokeStyle = 'white';
  ctx.strokeRect(10, 10, barWidth, 8);
};

input.newString:
const draw = () => {
  // Background: dark space gradient
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, '#001');
  bgGrad.addColorStop(1, '#000');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // Stars – tiny white points
  ctx.fillStyle = 'white';
  stars.forEach(s => {
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.radius, 0, Math.PI * 2);
    ctx.fill();
  });

  // Ship – triangle with optional flame for boost
  ctx.fillStyle = ship.shield > 0 ? 'gold' : 'white';
  ctx.beginPath();
  ctx.moveTo(ship.x, ship.y - ship.radius);
  ctx.lineTo(ship.x - ship.radius, ship.y + ship.radius);
  ctx.lineTo(ship.x + ship.radius, ship.y + ship.radius);
  ctx.closePath();
  ctx.fill();
  if (keys.boost && ship.fuel > 0) {
    ctx.fillStyle = 'orange';
    ctx.beginPath();
    ctx.moveTo(ship.x, ship.y + ship.radius);
    ctx.lineTo(ship.x - ship.radius / 2, ship.y + ship.radius + 8);
    ctx.lineTo(ship.x + ship.radius / 2, ship.y + ship.radius + 8);
    ctx.closePath();
    ctx.fill();
  }

  // Asteroids – gray circles with subtle stroke
  asteroids.forEach(a => {
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
    ctx.fillStyle = '#555';
    ctx.fill();
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.stroke();
  });

  // Energy orbs – cyan with radial glow
  orbs.forEach(o => {
    const orbGrad = ctx.createRadialGradient(o.x, o.y, 0, o.x, o.y, o.radius);
    orbGrad.addColorStop(0, '#0ff');
    orbGrad.addColorStop(1, '#004');
    ctx.fillStyle = orbGrad;
    ctx.beginPath();
    ctx.arc(o.x, o.y, o.radius, 0, Math.PI * 2);
    ctx.fill();
  });

  // HUD – fuel bar on top left with border
  ctx.fillStyle = 'lime';
  const barWidth = 100;
  ctx.fillRect(10, 10, (ship.fuel / 100) * barWidth, 8);
  ctx.strokeStyle = 'white';
  ctx.lineWidth = 1;
  ctx.strokeRect(10, 10, barWidth, 8);
};

